fn solve(n: i8) -> (i8, char) {
    // Compute the non-negative remainder of n modulo 4
    match n.rem_euclid(4) {
        1 => (0, 'A'), // n % 4 == 1
        2 => (1, 'B'), // n % 4 == 2 -> (n+1)%4 == 3 -> 'B'
        3 => (2, 'A'), // n % 4 == 3 -> (n+2)%4 == 1 -> 'A'
        0 => (1, 'A'), // n % 4 == 0 -> (n+1)%4 == 1 -> 'A'
        _ => unreachable!(),
    }
}

